"""Generate REPORT.md headline tables from runs/*/summary.json only (no hand-typed numbers)."""
import json
from pathlib import Path
here = Path(__file__).resolve().parent
PICK = [('h2d-ladder01', 'all', ['nmrom_q0_cn', 'nmrom_q24_cn', 'nmrom_q24_direct']),
        ('h2d-final04', 'sealed_opened_once', ['nmrom_q0_field_direct_tol1e-4_chol', 'nmrom_q32_cn', 'nmrom_q32_field_direct_tol1e-4_chol', 'nmrom_q96_field_direct_tol1e-4_chol']),
        ('h3d-profile03', 'all', ['nmrom_q0_cn', 'nmrom_q96_cn', 'nmrom_q96_field_direct_tol1e-4']),
        ('h3d-final08', 'paper_h3d_final_cohort', ['nmrom_q0_direct_tol1e-4_chol', 'nmrom_q96_cn', 'nmrom_q96_direct_tol1e-4_chol', 'nmrom_q96_field_direct_tol1e-4_chol'])]
CONTROLS = ('_NAMED', 'dst_exact_CONTROL', 'linear_bank_field_BASELINE', 'linear_bank_moments_BASELINE')
out = ['# hires-heat: generated headline tables', '', 'Generated by `make_report.py` from `runs/*/summary.json`; status of every number: audited development/sealed as labelled, single training seed, single GPU per job. Bar: all-times worst same-grid error <= 1 % AND >= 5x the named CN-CG (dt 0.025, rtol 1e-6) in the same allocation.', '']
for job, cohort, arms in PICK:
    f = here / 'runs' / job / 'summary.json'
    if not f.exists(): continue
    s = json.loads(f.read_text()); out += [f"## {job} — cohort `{cohort}` — {s['metadata']['gpu'].split(',')[0]}, job {s['metadata']['job_id']}, audit passed: {s['audit_passed']}", '',
        '| mesh | method | cases | err all-times % | err evolved % | GPU ms | x named CN-CG | fastest CN-CG with err <= method: x | coarse-grid FOM matched: x | failed solves | bar |', '|---|---|---:|---:|---:|---:|---:|---|---|---:|---|']
    for m in s['meshes']:
        if m['cohort'] != cohort: continue
        coarse = [r for r in m['rows'] if r['method'].startswith('coarse')]
        for r in m['rows']:
            rom = r['method'] in arms
            if not (rom or r['method'].endswith(CONTROLS) or r in coarse[-1:]): continue
            a, c = r.get('fastest_fom_error_le_rom_all_times'), r.get('fastest_coarse_fom_physical_evolved_le_rom')
            bar = ('PASS' if r['bar_error_le_1pct'] and r['bar_speedup_ge_5'] and not r['failures'] else 'miss') if rom else ('baseline/control' if not r['method'].startswith('fom') else 'named FOM')
            out.append(f"| {m['intervals']}^{'2' if job.startswith('h2d') else '3'} | {r['method']} | {r['cases']} | {100*r['error_all_times_worst']:.4f} | {100*r['error_evolved_worst']:.4f} | {r['device_ms_median']:.3f} | {r['speedup_vs_named_fom']:.2f} | "
                       + (f"{a['method']}: {a['speedup']:.2f}" if a else '-') + ' | ' + (f"{c['method']}: {c['speedup']:.3f}" if c else '-') + f" | {r['failures']} | {bar} |")
    out.append('')
out += ['## Glossary', '',
 '- **NM-ROM / nmrom_qN_…**: nonlinear-manifold reduced model: learned spatial bank (R functions), nonlinear head with K latent variables, plus N linear bank correction directions eliminated analytically. `q0` = fast setting, `q>0` = accurate settings.',
 '- **cn**: reduced Crank–Nicolson weak steps (dt 0.025, 20 nonlinear least-squares solves). **direct**: each output time fitted independently to the exactly propagated sine moments of the supplied initial field (5 batched solves); valid only for a linear autonomous PDE with eigenfunction tests. **field / moments**: initial fit to the full field or to its M test moments. **tol1e-4**: LM stationarity tolerance (default 1e-6). **chol**: Cholesky normal equations.',
 '- **err all-times / evolved**: worst over cases of the maximum over output times (including / excluding t=0) of relative L2 error against exact same-grid semidiscrete propagation.',
 '- **named CN-CG**: full-order Crank–Nicolson with unpreconditioned warm-started conjugate gradients, dt 0.025, relative tolerance 1e-6. **fastest CN-CG with err <= method**: fastest tested (dt, tolerance) full-order setting whose all-times error does not exceed the method’s. **coarse-grid FOM matched**: same CN-CG on a coarse grid, interpolated, with physical evolved error <= the method’s.',
 '- **x**: comparator GPU time divided by method GPU time, medians of 5 retained repetitions per case in one allocation; >1 means the method is faster.',
 '- **dst_exact_CONTROL**: exact fast-sine-transform solve, a labelled direct/transform control. **linear_bank_…_BASELINE**: free linear coefficients in the learned bank — a labelled baseline, not the NM-ROM.',
 '- **sealed_opened_once**: 16 draws (seed 791099) never seen by training, validation or any choice, evaluated once. **failed solves**: non-stationary LM exits or unconverged CG solves.']
(here / 'REPORT.md').write_text('\n'.join(out) + '\n'); print('\n'.join(out[:40]))
